{
  "measure_id": "MEAS-D6FD5BF4",
  "restatements": [
    {
      "clause_id": "§1",
      "text": "Allows parents of children eligible for public school to open an education savings account, into which the state will deposit 90% of the per-pupil funding that would normally go to the child's resident school district."
    },
    {
      "clause_id": "§2",
      "text": "Permits the funds in the education savings account to be spent on private school tuition, tutoring, textbooks, and approved online courses."
    }
  ],
  "findings": [
    {
      "id": "f1",
      "clause_id": "§2",
      "concern_id": "C41",
      "effect": "advances",
      "direction": null,
      "quote": "Account funds may be used for private school tuition, tutoring, textbooks, and approved online courses.",
      "mechanism": "Provides state funding to be used for private and alternative educational options outside the assigned public school.",
      "certainty": "stated"
    },
    {
      "id": "f2",
      "clause_id": "§1",
      "concern_id": "C42",
      "effect": "costs",
      "direction": null,
      "quote": "The state shall deposit into the account 90 percent of the state per-pupil funding the child's resident district would otherwise receive.",
      "mechanism": "Diverts a portion of per-pupil state funding away from public school districts when a resident child utilizes the savings account.",
      "certainty": "stated"
    },
    {
      "id": "f3",
      "clause_id": "§1",
      "concern_id": "C39",
      "effect": "advances",
      "direction": null,
      "quote": "A parent of a child eligible to attend public school may open an education savings account.",
      "mechanism": "Expands parents' ability to direct the state funding allocated for their child's education.",
      "certainty": "stated"
    }
  ],
  "analysis": [
    {
      "clause_id": "§1",
      "question_id": "Q1",
      "answer": "Currently, state education funds are distributed strictly to public school districts and charter schools. This measure allows parents to redirect 90% of a child's allotted per-pupil funding into an individual account to be used for private education expenses.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q2",
      "answer": "Direct costs include the 90% per-pupil allocations deposited into the accounts and the administrative expense of managing the program. Because eligibility applies to any child 'eligible to attend public school', the state may incur new net costs if students already attending private schools or being homeschooled claim the funds. Opportunity costs include reduced economies of scale for public schools.",
      "disputed": false
    },
    {
      "clause_id": "§2",
      "question_id": "Q3",
      "answer": "Parents who choose alternative education options benefit from the financial subsidy. Private schools, tutoring services, and educational material vendors benefit from the new source of revenue. Public school districts bear the cost of lost per-pupil revenue.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q4",
      "answer": "Parents may be incentivized to withdraw their children from public schools in favor of private or home-based options. Private educational providers might raise tuition or expand capacity in response to the increased purchasing power of families. Public school districts may struggle with budget shortfalls because their fixed costs (like building maintenance and administration) do not drop proportionately when a few students leave.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q5",
      "answer": "The measure addresses the problem of limited access to private education for families unable to afford alternative options by providing portable state funding. However, the mechanism creates a secondary issue by drawing funding away from public districts while potentially forcing the state to fund students who were already privately educated without state assistance.",
      "disputed": false
    },
    {
      "clause_id": "§2",
      "question_id": "Q7",
      "answer": "The effects of education savings accounts and voucher programs on student achievement and public school quality are empirically disputed. Some researchers find that such programs improve overall educational outcomes through market competition and by allowing students to find better-matching schools. Other researchers find that they drain vital resources from public school systems and that participating students can experience significant learning loss.",
      "disputed": true
    }
  ],
